# Stage 1 (portal order row) is authoritative for the fields whose text the
# voucher PDF prints on a single non-wrapping line and therefore truncates:
# hotel name, room type, dates, guest names, IBN, HCN.
# Stage 2 (voucher PDF) supplies the fields the order table never shows:
# address, hotel phone, bed configuration and meal plan.
row_raw = {{ Find_Booking.extracted_information }}
pdf_raw = {{ Extract_Data.extracted_information }}


def unwrap(value):
    if isinstance(value, dict) and "extracted_information" in value:
        value = value["extracted_information"]
    if isinstance(value, list):
        return value[0] if len(value) > 0 else {}
    if isinstance(value, dict):
        return value
    return {}


def text(value):
    if value is None:
        return None
    if not isinstance(value, str):
        value = str(value)
    value = value.strip()
    if not value or value.lower() in ("null", "none", "n/a", "-"):
        return None
    return value


def name_list(value):
    if isinstance(value, str):
        value = value.split(",")
    if not isinstance(value, list):
        return []
    names = []
    for item in value:
        name = text(item)
        if name:
            names.append(name)
    return names


row = unwrap(row_raw)
pdf = unwrap(pdf_raw)

# Guest count is not published anywhere on this portal, so it is derived from
# how many names the order row lists (repeats included: the portal fills one
# name slot per booked guest, often repeating the lead guest's name).
guest_names = name_list(row.get("guestNames"))
adult_count = len(guest_names)
if adult_count == 0:
    reported = row.get("guestCount")
    adult_count = reported if isinstance(reported, int) and reported > 0 else None

hotel_name = text(row.get("hotelName")) or text(pdf.get("voucherHotelName"))

# The voucher repeats the hotel name; surface it separately only when the two
# sources actually disagree, otherwise there is no second name to report.
voucher_hotel_name = text(pdf.get("voucherHotelName"))
supplier_hotel_name = None
if voucher_hotel_name and hotel_name and voucher_hotel_name.lower() != hotel_name.lower():
    supplier_hotel_name = voucher_hotel_name

booking = {
    "hotelName": hotel_name,
    "address": text(pdf.get("address")),
    "checkinDate": text(row.get("checkinDate")),
    "checkoutDate": text(row.get("checkoutDate")),
    "adultCount": adult_count,
    "guestNames": guest_names if guest_names else None,
    "childrenCount": None,
    "supplierHotelName": supplier_hotel_name,
    "roomCategory": text(row.get("roomCategory")) or text(pdf.get("voucherRoomType")),
    "mealPlan": text(pdf.get("mealPlan")),
    "bedType": text(pdf.get("bedType")),
    "phone": text(pdf.get("phone")),
    "ibn": text(row.get("ibn")) or text(pdf.get("voucherBookingNo")),
    "hcn": text(row.get("hcn")) or text(pdf.get("voucherConfirmationNo")),
}

return {"parsed_booking": [booking]}
